<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { api, getData } from '@/api'; import type { Item } from '@/types'; import { typeText, categoryText, formatTime } from '@/utils/labels'; import { ElMessage, ElMessageBox } from 'element-plus'
interface Log { id: number; operator: string; action: string; targetType: string; targetId: number; detail: string; createdAt: string }
const stats = ref<Record<string, number>>({}); const pending = ref<Item[]>([]); const logs = ref<Log[]>([]); const tab = ref('review')
async function load() { [stats.value, pending.value, logs.value] = await Promise.all([getData<Record<string, number>>(api.get('/admin/statistics')), getData<Item[]>(api.get('/admin/pending-items')), getData<Log[]>(api.get('/admin/logs'))]) }
async function review(item: Item, approved: boolean) { const { value = '' } = await ElMessageBox.prompt(approved ? '可填写审核备注' : '请说明驳回原因', approved ? '审核通过' : '审核驳回', { inputType: 'textarea', confirmButtonText: '确认', cancelButtonText: '取消', inputValidator: (v) => approved || !!v.trim() || '驳回时必须填写原因' }); await api.post(`/admin/items/${item.id}/review`, { approved, comment: value }); ElMessage.success('审核完成'); load() }
onMounted(load)
</script>
<template><section class="dashboard-page admin-page"><div class="page-title"><span class="eyebrow">ADMIN CONSOLE</span><h1>管理后台</h1><p>审核校园信息，维护互助社区的真实与安全。</p></div><div class="stat-grid"><div v-for="(value, label) in stats" :key="label" class="stat-card"><span>{{ label }}</span><b>{{ value }}</b></div></div><el-tabs v-model="tab" class="dashboard-tabs"><el-tab-pane :label="`待审核（${pending.length}）`" name="review"><el-table :data="pending"><el-table-column label="类型" width="100"><template #default="s">{{ typeText[s.row.postType] }}</template></el-table-column><el-table-column prop="title" label="标题" min-width="180"/><el-table-column label="分类"><template #default="s">{{ categoryText[s.row.category] }}</template></el-table-column><el-table-column prop="location" label="地点"/><el-table-column prop="publisherName" label="发布者"/><el-table-column label="操作" width="170"><template #default="s"><el-button type="success" size="small" @click="review(s.row, true)">通过</el-button><el-button type="danger" size="small" plain @click="review(s.row, false)">驳回</el-button></template></el-table-column></el-table><el-empty v-if="!pending.length" description="目前没有待审核信息"/></el-tab-pane><el-tab-pane label="操作日志" name="logs"><el-table :data="logs"><el-table-column prop="operator" label="操作人"/><el-table-column prop="action" label="操作"/><el-table-column prop="targetType" label="对象"/><el-table-column prop="targetId" label="编号"/><el-table-column prop="detail" label="说明"/><el-table-column label="时间" width="170"><template #default="s">{{ formatTime(s.row.createdAt) }}</template></el-table-column></el-table></el-tab-pane></el-tabs></section></template>
